cat > /tmp/mdcheck.mjs <<'EOF'
import MarkdownIt from '/home/sandbox/workspace/node_modules/markdown-it/index.mjs';
const md = new MarkdownIt({ html: false, linkify: true, breaks: true });
const d = md.renderer.rules.link_open;
