const cases = [
  '# Title\n\n**bold** *it* `code`\n- a\n- b',
  '<img src=x onerror=alert(1)>\n<script>alert(1)</script>',
  '[x](javascript:alert(1))',
  '[ok](https://example.com)',
  'line one\nline two',
];
for (const c of cases) console.log(JSON.stringify(c), '=>\n' + md.render(c));
EOF
node /tmp/mdcheck.mjs; rm -f /tmp/mdcheck.mjs; echo ---; which chromium chromium-browser google-chrome 2>/dev/null; ls ~/.cache/ms-playwright 2>/dev/null; echo "browser check done"
